alter table public.admin_roles add column if not exists role text not null default 'ADMINISTRADOR';
update public.admin_roles set role='ADMINISTRADOR' where role is null or role not in ('LIDER','ADMINISTRADOR','SUPORTE','ATENDENTE');
alter table public.admin_roles drop constraint if exists admin_roles_role_check;
alter table public.admin_roles add constraint admin_roles_role_check check (role in ('LIDER','ADMINISTRADOR','SUPORTE','ATENDENTE'));
create index if not exists admin_roles_role_idx on public.admin_roles(role);
create or replace function public.is_site_leader(uid uuid) returns boolean language sql stable security definer set search_path='' as $$ select lower(coalesce((select email from auth.users where id=uid),''))='willianwca2011@gmail.com' $$;
create or replace function public.get_admin_role(uid uuid default auth.uid()) returns text language sql stable security definer set search_path='' as $$ select case when public.is_site_leader(uid) then 'LIDER' when exists(select 1 from public.admin_roles where user_id=uid and role='ADMINISTRADOR') then 'ADMINISTRADOR' when exists(select 1 from public.admin_roles where user_id=uid and role='SUPORTE') then 'SUPORTE' when exists(select 1 from public.admin_roles where user_id=uid and role='ATENDENTE') then 'ATENDENTE' else null end $$;
create or replace function public.is_admin(uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path='' as $$ select public.get_admin_role(uid) is not null $$;
create or replace function public.can_admin_action(uid uuid, action text) returns boolean language sql stable security definer set search_path='' as $$ select case public.get_admin_role(uid) when 'LIDER' then true when 'ADMINISTRADOR' then action <> 'MANAGE_ROLES' when 'SUPORTE' then action in ('VIEW_ADMIN','VIEW_USERS','VIEW_CHATS','REVIEW_CHAT','VIEW_SUPPORT','SUPPORT_REPLY','SUPPORT_FINAL','VIEW_REPORTS','REPORT_DECISION') when 'ATENDENTE' then action in ('VIEW_ADMIN','VIEW_SUPPORT','SUPPORT_REPLY','SUPPORT_FORWARD','VIEW_CHATS','REVIEW_CHAT') else false end $$;
drop function if exists public.moderate_user(uuid,text,text,timestamptz);
drop function if exists public.update_report_status(uuid,text,text);
create or replace function public.set_admin_role(target uuid,new_role text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_site_leader() then raise exception 'ONLY_SITE_LEADER'; end if; if target is null then raise exception 'INVALID_USER'; end if; if new_role not in ('ADMINISTRADOR','SUPORTE','ATENDENTE') then raise exception 'INVALID_ROLE'; end if; if public.is_site_leader(target) then raise exception 'PRIMARY_LEADER_PROTECTED'; end if; update public.profiles set is_admin=true,updated_at=now() where id=target; if not found then raise exception 'USER_NOT_FOUND'; end if; insert into public.admin_roles(user_id,created_by,role) values(target,auth.uid(),new_role) on conflict(user_id) do update set role=excluded.role; end $$;
create or replace function public.remove_admin_role(target uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_site_leader() then raise exception 'ONLY_SITE_LEADER'; end if; if target is null or public.is_site_leader(target) then raise exception 'PRIMARY_LEADER_PROTECTED'; end if; delete from public.admin_roles where user_id=target; update public.profiles set is_admin=false,updated_at=now() where id=target; end $$;
create or replace function public.moderate_user(target uuid,new_status text,reason text,until_at timestamptz default null) returns void language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); begin if actor is null or not public.can_admin_action(actor,'MODERATE_USER') then raise exception 'INSUFFICIENT_ROLE'; end if; if target is null or public.is_site_leader(target) then raise exception 'PROTECTED_USER'; end if; if new_status not in ('ACTIVE','SUSPENDED','BANNED') then raise exception 'INVALID_STATUS'; end if; if new_status='SUSPENDED' and (until_at is null or until_at<=now()) then raise exception 'INVALID_SUSPENSION_DATE'; end if; if new_status<>'SUSPENDED' then until_at:=null; end if; update public.profiles set account_status=new_status,suspended_until=until_at,moderation_reason=nullif(trim(reason),''),updated_at=now() where id=target; if not found then raise exception 'USER_NOT_FOUND'; end if; insert into public.admin_audit_logs(admin_id,action,target_user_id,metadata,created_at) values(actor,'USER_STATUS_CHANGED',target,jsonb_build_object('status',new_status,'reason',reason,'until_at',until_at),now()); end $$;
create or replace function public.admin_forward_support_ticket(p_ticket_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ begin if not public.can_admin_action(auth.uid(),'SUPPORT_FORWARD') then raise exception 'INSUFFICIENT_ROLE'; end if; update public.support_tickets set status='IN_PROGRESS',updated_at=now() where id=p_ticket_id; if not found then raise exception 'TICKET_NOT_FOUND'; end if; return true; end $$;
create or replace function public.admin_update_support_ticket(p_ticket_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$ declare role text:=public.get_admin_role(auth.uid());begin if role is null then raise exception 'INSUFFICIENT_ROLE';end if;if p_status not in ('OPEN','IN_PROGRESS','WAITING_USER','RESOLVED','CLOSED') then raise exception 'INVALID_STATUS';end if;if p_status in ('RESOLVED','CLOSED') and role not in ('LIDER','ADMINISTRADOR','SUPORTE') then raise exception 'FINAL_DECISION_REQUIRED';end if;update public.support_tickets set status=p_status,updated_at=now() where id=p_ticket_id;if not found then raise exception 'TICKET_NOT_FOUND';end if;end $$;
create or replace function public.update_report_status(report_id uuid,new_status text,note text default null) returns void language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid();role text:=public.get_admin_role(actor);begin if role is null or role not in ('LIDER','ADMINISTRADOR','SUPORTE') then raise exception 'FINAL_DECISION_REQUIRED';end if;if new_status not in ('PENDING','REVIEWING','RESOLVED','REJECTED') then raise exception 'INVALID_REPORT_STATUS';end if;update public.reports set status=new_status,moderator_id=actor,resolution_note=note,updated_at=now() where id=report_id;if not found then raise exception 'REPORT_NOT_FOUND';end if;end $$;
grant execute on function public.set_admin_role(uuid,text) to authenticated;
grant execute on function public.remove_admin_role(uuid) to authenticated;
grant execute on function public.moderate_user(uuid,text,text,timestamptz) to authenticated;
grant execute on function public.get_admin_role(uuid) to authenticated;
grant execute on function public.is_admin(uuid) to authenticated;
grant execute on function public.admin_forward_support_ticket(uuid) to authenticated;
grant execute on function public.admin_update_support_ticket(uuid,text) to authenticated;
grant execute on function public.update_report_status(uuid,text,text) to authenticated;
